def make_profile(owner="alice", version="v1"):
    return {"owner": owner, "version": version}

def test_owner_match_happy_path_and_cache_reuse():
    store = {}
    task = make_task("alice", "v1", "do thing", "cv1")
    profile = make_profile("alice", "v1")

    calls = []
    def compute():
        calls.append(1)
        return "result"

    assert evaluate(store, task, profile, compute) == "result"
    assert evaluate(store, task, profile, compute) == "result"
    assert len(calls) == 1

def test_owner_mismatch_raises_before_store_and_compute():
    store = {"x": "nope"}
    task = make_task("alice")
    profile = make_profile("bob")

    class Boom(Exception):
        pass

    def compute():
        raise Boom()

    try:
        evaluate(store, task, profile, compute)
    except PermissionError:
        pass
    else:
        raise AssertionError("PermissionError not raised")

    # store must be unchanged
    assert store == {"x": "nope"}

def test_version_mismatch_returns_none_no_side_effects():
    store = {"x": "nope"}
    task = make_task("alice", version="old")
    profile = make_profile("alice", version="new")

    seen = []
    def compute():
        seen.append(1)
        return "computed"

    result = evaluate(store, task, profile, compute)
    assert result is None
    assert store == {"x": "nope"}
    assert seen == []

def test_cache_key_covers_owner_profile_version_criteria_job_text():
    store = {}
    calls = []
    def compute():
        calls.append(task)
        return "cached:" + str(task)

    owner_a = make_task("alice", "v1", "job", "cv1")
    profile_a = make_profile("alice", "v1")
    assert evaluate(store, owner_a, profile_a, compute) == "cached:" + str(owner_a)

    # same owner/profile.version but different job_text -> recompute
    other_task = make_task("alice", "v1", "other job", "cv1")
    assert evaluate(store, other_task, profile_a, compute) == "cached:" + str(other_task)
    assert len(calls) == 2

    # different criteria_version -> recompute
    crit_task = make_task("alice", "v1", "job", "cv2")
    assert evaluate(store, crit_task, profile_a, compute) == "cached:" + str(crit_task)
    assert len(calls) == 3

    # different owner -> PermissionError
    try:
        evaluate(store, make_task("mallory", "v1", "job", "cv1"), profile_a, compute)
    except PermissionError:
        pass
    else:
        raise AssertionError("PermissionError not raised for different owner")

    # 0 and None values: unchanged input reuses even 0/None
    zero_task = make_task("alice", version=0, job_text=0, criteria_version=None)
    profile_zero = make_profile("alice", version=0)
    zero_store = {}
    zero_calls = []
    def zero_compute():
        zero_calls.append(1)
        return "zero"
    assert evaluate(zero_store, zero_task, profile_zero, zero_compute) == "zero"
    assert evaluate(zero_store, zero_task, profile_zero, zero_compute) == "zero"
    assert len(zero_calls) == 1
    assert zero_store == {( "alice", 0, None, 0): "zero"}

def test_compute_exception_propagates_and_not_cached():
    store = {}
    task = make_task("alice")
    profile = make_profile("alice")
    result = []
    def compute():
        result.append("called")
        raise ValueError("boom")
    try:
        evaluate(store, task, profile, compute)
    except ValueError:
        pass
    else:
        raise AssertionError("ValueError not propagated")
    assert result == ["called"]
    assert store == {}

def test_owner_mismatch_even_when_cached():
    # owner mismatch raises even if a stale key exists; store untouched
    store = {"stale": 1}
    task = make_task("alice")
    profile = make_profile("mallory")
    def compute():
        raise RuntimeError("should not be called")
    try:
        evaluate(store, task, profile, compute)
    except PermissionError:
        pass
    else:
        raise AssertionError("PermissionError not raised")
    assert store == {"stale": 1}

